#include <cstdio>
#include <vector>
#include <algorithm>

int n, totalCount, sumArr[15], answer;
std::vector<int> vecs[15];

void buildSequences(int level, int num);
void explore(int x);

int main() {
    scanf("%d", &n);
    buildSequences(0, 0);
    for (int i = 0; i <= 7; i++) {
        std::sort(vecs[i].begin(), vecs[i].end());
    }
    totalCount = 0;
    for (int i = 1; i <= 9; i++) {
        explore(i);
    }
    printf("%d\n", answer);
    return 0;
}

void buildSequences(int level, int num) {
    if (level == 7) return;
    totalCount++;
    int val = ((totalCount - num) % 998244353 + 998244353) % 998244353;
    vecs[level].push_back(val);
    sumArr[level] = (sumArr[level] + val) % 1000000007;
    for (int digit = 0; digit <= 9; digit++) {
        buildSequences(level + 1, num * 10 + digit);
    }
}

void explore(int x) {
    if (x > n) return;
    if (x * 1000000 + 999999 <= n && x * 10 * 1000000 > n) {
        int current = totalCount;
        for (int i = 0, mul = 1; i <= 6; i++, mul *= 10) {
            int sizeVec = vecs[i].size();
            int diffVal = ((current - x * mul) % 998244353 + 998244353) % 998244353;
            int pos = (int)(lower_bound(vecs[i].begin(), vecs[i].end(), 1000000000 - diffVal) - vecs[i].begin());
            answer = (answer + diffVal * sizeVec + sumArr[i]) % 1000000007;
            answer = (answer - 998244353 * (sizeVec - pos) % 1000000007 + 1000000007) % 1000000007;
            totalCount += sizeVec;
        }
        return;
    }
    totalCount++;
    answer = (answer + ((totalCount - x) % 998244353 + 998244353) % 998244353) % 1000000007;
    for (int i = 0; i <= 9; i++) {
        explore(x * 10 + i);
    }
}
